SELECT Job_Role, ROUND(AVG(Salary), 2) 
FROM STAFF 
GROUP BY Job_Role;

SELECT STUDENT.Name, CLASS.Room_No 
FROM STUDENT, CLASS 
WHERE STUDENT.Class_ID = CLASS.Class_ID;

1) SELECT Dept, COUNT(*) FROM EMPLOYEE GROUP BY Dept;
2) SELECT MAX(Salary) FROM EMPLOYEE WHERE Dept = 'Sales';
3) SELECT Dept FROM EMPLOYEE GROUP BY Dept HAVING SUM(Salary) > 500000;
